use sha2::{Digest,Sha256};
use std::{fs,path::PathBuf,process::Command,sync::atomic::{AtomicU64,Ordering}};
static NEXT:AtomicU64=AtomicU64::new(0);
struct Fixture(PathBuf);
impl Fixture{fn new()->Self{let path=std::env::temp_dir().join(format!("justfit-distribution-options-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));fs::create_dir(&path).unwrap();Self(path)}fn project(&self)->PathBuf{let path=self.0.join("project");fs::create_dir_all(path.join("config/nodes")).unwrap();let root=PathBuf::from(env!("CARGO_MANIFEST_DIR")).parent().unwrap().parent().unwrap().to_path_buf();let bytes=fs::read(root.join("config/nodes/m4.json")).unwrap();fs::write(path.join("config/nodes/m4.json"),&bytes).unwrap();fs::write(path.join("package-manifest.json"),serde_json::to_vec(&serde_json::json!({"config/nodes/m4.json":format!("{:x}",Sha256::digest(bytes))})).unwrap()).unwrap();path}}
impl Drop for Fixture{fn drop(&mut self){fs::remove_dir_all(&self.0).unwrap();}}
fn cli()->Command{let binary=std::env::var_os("JUSTFIT_TEST_DISTRIBUTION_CLI").unwrap_or_else(||env!("CARGO_BIN_EXE_justfit-rs").into());let mut c=Command::new(binary);c.env("PATH","");c}
#[test]fn public_help_exposes_gguf_and_released_server_options(){let out=cli().args(["model","prepare","--help"]).output().unwrap();assert!(out.status.success());assert!(String::from_utf8_lossy(&out.stdout).contains("--mmproj"));let out=cli().args(["serve","--help"]).output().unwrap();assert!(out.status.success());let help=String::from_utf8(out.stdout).unwrap();for flag in ["--api-key","--max-context","--max-cache-disk","--allowed-origin","--queue-size","--idle-release","--decode-share","--max-request-size","--served-model-name"]{assert!(help.contains(flag),"{flag}");}}
#[test]fn public_options_reach_native_and_http_plans_without_setup_or_secret_leaks(){let fixture=Fixture::new();let root=fixture.project();let out=cli().args(["serve","--project"]).arg(&root).args(["--node","m4","--model","/unused-local","--no-ane-vision","--dry-run","--max-context","32K","--max-memory","20GiB","--max-cache-disk","0","--host","0.0.0.0","--allowed-host","test.local","--allowed-origin","https://example.com","--api-key","fixture-secret","--served-model-name","alias","--announce-served-name","--request-timeout","1.5m","--queue-size","7","--max-image-pixels","65537","--max-request-size","16M","--idle-release","off","--decode-share","0.25"]).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let v:serde_json::Value=serde_json::from_slice(&out.stdout).unwrap();assert_eq!(v["config"]["native"][3],"32768");assert_eq!(v["config"]["native"][4],"21474836480");assert_eq!(v["config"]["native"][5],"0");assert_eq!(v["config"]["host"],"0.0.0.0");assert_eq!(v["config"]["request_timeout"],90.);assert_eq!(v["config"]["queue_size"],7);assert_eq!(v["environment"]["JUSTFIT_API_KEY"],"[redacted]");assert!(!String::from_utf8_lossy(&out.stdout).contains("fixture-secret"));assert!(!root.join("local-state").exists());}
#[test]fn inherited_auth_key_is_retained_and_invalid_options_do_not_create_workspace(){let fixture=Fixture::new();let root=fixture.project();let out=cli().env("JUSTFIT_API_KEY","inherited-fixture-key").args(["serve","--project"]).arg(&root).args(["--node","m4","--model","/unused","--no-ane-vision","--dry-run"]).output().unwrap();assert!(out.status.success());let v:serde_json::Value=serde_json::from_slice(&out.stdout).unwrap();assert_eq!(v["environment"]["JUSTFIT_API_KEY"],"[redacted]");for (flag,value) in [("--queue-size","0"),("--request-timeout","nan"),("--max-memory","-1"),("--api-key","bad key")]{let absent=fixture.0.join("not-created");let out=cli().args(["serve","--project"]).arg(&absent).args(["--node","m4",flag,value]).output().unwrap();assert_eq!(out.status.code(),Some(2));assert!(!absent.exists());}}
